"""Shared configuration for the data generator, explainer, dashboard and analytics."""

import os
import uuid
from pathlib import Path

import yaml
from dotenv import load_dotenv

ROOT = Path(__file__).resolve().parent.parent
PROFILES_DIR = ROOT / "datagen" / "profiles"

# Precedence: real environment > .env.local (your settings: watsonx, branding) > .env (generated by Terraform).
load_dotenv(ROOT / ".env.local")
load_dotenv(ROOT / ".env")


def require(name: str) -> str:
    value = os.getenv(name)
    if not value:
        raise SystemExit(
            f"Missing environment variable {name}. Run `make up` (terraform apply) "
            f"to generate .env, or export it manually."
        )
    return value


def kafka_conf(**overrides) -> dict:
    conf = {
        "bootstrap.servers": require("BOOTSTRAP_SERVERS"),
        "security.protocol": "SASL_SSL",
        "sasl.mechanisms": "PLAIN",
        "sasl.username": require("KAFKA_API_KEY"),
        "sasl.password": require("KAFKA_API_SECRET"),
    }
    conf.update(overrides)
    return conf


def consumer_conf(group_prefix: str, from_beginning: bool = True, **overrides) -> dict:
    return kafka_conf(
        **{
            "group.id": f"{group_prefix}-{uuid.uuid4().hex[:8]}",
            "auto.offset.reset": "earliest" if from_beginning else "latest",
            "enable.auto.commit": False,
            **overrides,
        }
    )


def schema_registry_conf() -> dict:
    return {
        "url": require("SCHEMA_REGISTRY_URL"),
        "basic.auth.user.info": f"{require('SCHEMA_REGISTRY_API_KEY')}:{require('SCHEMA_REGISTRY_API_SECRET')}",
    }


def profile_name() -> str:
    return os.getenv("PROFILE", "apparel_drops")


def load_profile(name: str | None = None) -> dict:
    name = name or profile_name()
    path = PROFILES_DIR / f"{name}.yaml"
    if not path.exists():
        available = ", ".join(sorted(p.stem for p in PROFILES_DIR.glob("*.yaml")))
        raise SystemExit(f"Unknown profile '{name}'. Available: {available}")
    with path.open() as f:
        profile = yaml.safe_load(f)

    # Quick re-skin for a customer meeting without editing the YAML.
    brand = profile.setdefault("brand", {})
    if os.getenv("BRAND_NAME"):
        brand["name"] = os.environ["BRAND_NAME"]
    if os.getenv("BRAND_COLOR"):
        brand["primary_color"] = os.environ["BRAND_COLOR"]
    return profile
